int32_t n_remaining() const {
    return n_predict_max == -1 ? -1 : n_predict_max - (int32_t) stats.n_gen;
}

bool has_budget() const {
    return n_predict_max == -1 || n_remaining() > 0;
}

bool process_token(completion_token_output & result, server_slot & slot) {
    // remember which tokens were sampled - used for repetition penalties during sampling
    const std::string token_str = result.text_to_send;
    slot.sampled = result.tok;

    slot.generated_text += token_str;
    if (slot.task->params.return_tokens) {
        slot.generated_tokens.push_back(result.tok);
    }
    slot.has_next_token = true;

    // check if there is incomplete UTF-8 character at the end
    bool incomplete = validate_utf8(slot.generated_text) < slot.generated_text.size();

    // search stop word and delete it
    if (!incomplete) {
        size_t pos = std::min(slot.n_sent_text, slot.generated_text.size());

        const std::string str_test = slot.generated_text.substr(pos);
        bool send_text = true;

        size_t stop_pos = slot.find_stopping_strings(str_test, token_str.size(), true);
        if (stop_pos != std::string::npos) {
            slot.generated_text.erase(
                slot.generated_text.begin() + pos + stop_pos,
                slot.generated_text.end());
            pos = std::min(slot.n_sent_text, slot.generated_text.size());
        } else if (slot.has_next_token && !llama_vocab_is_eog(vocab, result.tok) ) {
            stop_pos = slot.find_stopping_strings(str_test, token_str.size(), false);
            send_text = stop_pos == std::string::npos;
        }

        // check if there is any token to predict
        if (send_text) {
            // no send the stop word in the response
            result.text_to_send = slot.generated_text.substr(pos, std::string::npos);
            slot.n_sent_text += result.text_to_send.size();
            // add the token to slot queue and cache
        } else {
            result.text_to_send = "";
        }

        slot.add_token(result);
        if (slot.task->params.stream) {
            send_partial_response(slot, result, false);
        }
    }

    if (incomplete) {
        slot.has_next_token = true;
    }

    // if context shifting is disabled, make sure that we don't run out of context
    if (!params_base.ctx_shift && slot.prompt.n_tokens() + 1 >= slot.n_ctx) {
        slot.truncated      = true;
        slot.stop           = STOP_TYPE_LIMIT;
        slot.has_next_token = false;

        SLT_DBG(slot, "stopped due to running out of context capacity, prompt.n_tokens() = %d, task.n_tokens = %d, n_gen = %d, n_ctx = %d\n",
                slot.prompt.n_tokens(), slot.task->n_tokens(), (int) slot.stats.n_gen, slot.n_ctx);
    }

    // check the limits
    if (slot.stats.n_gen > 0 && slot.has_next_token && !slot.has_budget()) {
        slot.stop           = STOP_TYPE_LIMIT;
        slot.has_next_token = false;

        SLT_DBG(slot, "stopped by limit, n_gen = %d, n_predict = %d\n", (int) slot.stats.n_gen, slot.task->params.n_predict);
    }

if (llama_vocab_is_eog(vocab, result.tok)) {
    slot.stop           = STOP_TYPE_EOS;
    slot.has_next_token = false;

    SLT_DBG(slot, "%s", "stopped by EOS\n");
}

SLT_DBG(slot, "n_gen = %d, n_remaining = %d, next token: %5d '%s'\n", (int) slot.stats.n_gen, slot.n_remaining(), result.tok, token_str.c_str());

return slot.has_next_token; // continue

void send_final_response(server_slot & slot) {
    auto res = std::make_unique<server_task_result_cmpl_final>();

    res->id      = slot.task->id;
    res->id_slot = slot.id;

    res->index = slot.task->index;

    // keep copy of last generated text for debugging purposes
    if (slots_debug) {
        slot.debug_generated_text = slot.generated_text;
    }

    // in stream mode, content and tokens are already in last partial chunk
    if (slot.task->params.stream) {
        res->content     = "";
        res->tokens      = llama_tokens{};
    } else {
        res->content     = std::move(slot.generated_text);
        res->tokens      = std::move(slot.generated_tokens);
    }
    res->stats           = slot.stats;
    res->prompt          = slot.task->tokens.detokenize(ctx_tgt, true);
    res->response_fields = std::move(slot.task->params.response_fields);

    res->truncated             = slot.truncated;
    res->n_decoded             = slot.stats.n_gen;
    res->n_prompt_tokens       = slot.task->n_tokens();
    res->n_prompt_tokens_cache = slot.stats.n_prompt_cached;
    res->n_tokens_cached       = slot.prompt.n_tokens();
    res->has_new_line          = slot.has_new_line;
    res->stopping_word         = slot.stopping_word;
    res->stop                  = slot.stop;
    res->post_sampling_probs   = slot.task->params.post_sampling_probs;

    res->verbose           = slot.task->params.verbose;
    res->stream            = slot.task->params.stream;
    res->include_usage     = slot.task->params.include_usage;
    res->res_type          = slot.task->params.res_type;
    res->oaicompat_model   = slot.task->params.oaicompat_model;

slot.i_batch = -1;

common_sampler_accept(slot.smpl.get(), id, true);

// here we have synchronized the llama_context (due to the sampling above), so we can do time measurement
const int64_t t_now = ggml_time_us();

slot.stats.n_gen += 1;

if (slot.stats.n_gen == 1) {
    slot.stats.update_prompt_last();
    slot.t_print_last = t_now;
    slot.n_gen_last = 0;

task_result_state::task_result_state(const common_chat_parser_params & chat_parser_params)
    : chat_parser_params(chat_parser_params)
    , oai_resp_id("resp_" + random_string())
    , oai_resp_reasoning_id("rs_" + random_string())
    , oai_resp_message_id("msg_" + random_string()) {
    if (chat_parser_params.is_continuation && !chat_parser_params.echo) {
        // initialize chat_msg to avoid emitting a delta containing the assistant prefill
        chat_msg = common_chat_parse("", true, chat_parser_params);
    }
}

common_chat_msg task_result_state::update_chat_msg(
        const std::string & text_added,
        bool is_partial,
        std::vector<common_chat_msg_diff> & diffs,
        bool filter_tool_calls) {
    generated_text += text_added;
    auto msg_prv_copy = chat_msg;
    //SRV_DBG("Parsing chat message: %s\n", generated_text.c_str());
    auto new_msg = common_chat_parse(
        generated_text,
        is_partial,
        chat_parser_params);
    if (!new_msg.empty()) {
        new_msg.set_tool_call_ids(generated_tool_call_ids, gen_tool_call_id);
        chat_msg = new_msg;
        auto all_diffs = common_chat_msg_diff::compute_diffs(msg_prv_copy, chat_msg);

json server_task_result_cmpl_final::to_json_oaicompat_chat() {
    std::string finish_reason = "length";
    common_chat_msg msg;
    if (!oaicompat_msg.empty()) {
        msg = oaicompat_msg;
    } else {
        msg.role = "assistant";
        msg.content = content;
    }
    if (stop == STOP_TYPE_WORD || stop == STOP_TYPE_EOS) {
        finish_reason = msg.tool_calls.empty() ? "stop" : "tool_calls";
    }

    json choice {
        {"finish_reason", finish_reason},
        {"index", index},
        {"message", msg.to_json_oaicompat()},
    };

virtual void update(task_result_state & state) override {
    is_updated = true;
    oaicompat_msg = state.update_chat_msg(content, false, oaicompat_msg_diffs);

    oai_resp_id = state.oai_resp_id;
    oai_resp_reasoning_id = state.oai_resp_reasoning_id;
    oai_resp_message_id = state.oai_resp_message_id;
}

size_t validate_utf8(const std::string& text) {
    size_t len = text.size();
    if (len == 0) return 0;

    // Check the last few bytes to see if a multi-byte character is cut off
    for (size_t i = 1; i <= 4 && i <= len; ++i) {
        unsigned char c = text[len - i];
        // Check for start of a multi-byte sequence from the end
        if ((c & 0xE0) == 0xC0) {
            // 2-byte character start: 110xxxxx
            // Needs at least 2 bytes
            if (i < 2) return len - i;
        } else if ((c & 0xF0) == 0xE0) {
            // 3-byte character start: 1110xxxx
            // Needs at least 3 bytes
            if (i < 3) return len - i;
        } else if ((c & 0xF8) == 0xF0) {
            // 4-byte character start: 11110xxx
            // Needs at least 4 bytes
            if (i < 4) return len - i;
        }
    }

    // If no cut-off multi-byte character is found, return full length
    return len;

